import time
from functools import wraps
from typing import Callable, Any

def benchmark(func: Callable) -> Callable:
    """Decorator that measures and logs the elapsed execution time of a function."""
    @wraps(func) # Preserves function name, docstrings, and signature
    def wrapper(*args: Any, **kwargs: Any) -> Any:
        start_time = time.perf_counter()
        result = func(*args, **kwargs)
        duration_ms = (time.perf_counter() - start_time) * 1000.0
        print(f"[BENCHMARK] {func.__name__}() executed in {duration_ms:.2f} ms")
        return result
    return wrapper

@benchmark
def compute_heavy_embeddings(n: int) -> int:
    return sum(i * i for i in range(n))

# Usage: Automatically logs execution duration
val = compute_heavy_embeddings(5_000_000)
